/* KIN-MART Local Charts - mini API compatible avec new Chart(canvas,{type,data,options}) pour bar/line/doughnut. Fonctionne hors-ligne. */
class Chart{constructor(c,cfg){this.c=typeof c==='string'?document.getElementById(c):c;this.cfg=cfg;this.draw()}draw(){if(!this.c)return;const x=this.c.getContext('2d'),w=this.c.width=this.c.clientWidth*devicePixelRatio,h=this.c.height=this.c.clientHeight*devicePixelRatio;x.scale(devicePixelRatio,devicePixelRatio);const W=this.c.clientWidth,H=this.c.clientHeight;x.clearRect(0,0,W,H);const labels=this.cfg.data?.labels||[],ds=(this.cfg.data?.datasets||[])[0]||{},vals=(ds.data||[]).map(Number),red='#d71920',gray='#e5e7eb';if(!vals.length){x.fillStyle='#999';x.font='14px sans-serif';x.fillText('Aucune donnée',20,30);return}if(this.cfg.type==='doughnut'){const sum=vals.reduce((a,b)=>a+b,0)||1;let a=-Math.PI/2;vals.forEach((v,i)=>{const n=a+v/sum*Math.PI*2;x.beginPath();x.arc(W/2,H/2,Math.min(W,H)*.32,a,n);x.arc(W/2,H/2,Math.min(W,H)*.18,n,a,true);x.closePath();x.fillStyle=['#d71920','#111','#6b7280','#ef4444','#9ca3af'][i%5];x.fill();a=n});return}const pad=38,max=Math.max(...vals,1),cw=(W-pad*2)/Math.max(vals.length,1);x.strokeStyle=gray;x.beginPath();x.moveTo(pad,10);x.lineTo(pad,H-pad);x.lineTo(W-10,H-pad);x.stroke();if(this.cfg.type==='line'){x.strokeStyle=red;x.lineWidth=2;x.beginPath();vals.forEach((v,i)=>{const px=pad+cw*(i+.5),py=H-pad-(v/max)*(H-pad-20);i?x.lineTo(px,py):x.moveTo(px,py);x.fillStyle=red;x.beginPath();x.arc(px,py,3,0,Math.PI*2);x.fill()});x.stroke()}else vals.forEach((v,i)=>{const bh=(v/max)*(H-pad-20),bx=pad+cw*i+cw*.18;x.fillStyle=red;x.fillRect(bx,H-pad-bh,cw*.64,bh)});x.fillStyle='#777';x.font='11px sans-serif';labels.forEach((l,i)=>{const text=String(l).slice(0,10);x.fillText(text,pad+cw*i+3,H-10)})}}window.Chart=Chart;